class Solution {
  public long numberOfSubarrays(int[] nums) {
    Deque<long[]> stack =
        new ArrayDeque<>(); // {value, how many times it appears with nothing larger in between}
    long answer = 0;
    for (int value : nums) {
      while (!stack.isEmpty() && stack.peek()[0] < value) stack.pop();
      if (!stack.isEmpty() && stack.peek()[0] == value) {
        answer += stack.peek()[1] + 1; // pair with each earlier copy, plus the single element
        stack.peek()[1]++;
      } else {
        stack.push(new long[] {value, 1});
        answer++;
      }
    }
    return answer;
  }
}
